#!/bin/sh
set -eu
if [ "$#" -lt 1 ] || [ "$#" -gt 2 ]; then echo "Usage: $0 TARGET_COPY [blocker|ui|native|ui-v0.1.1|native-v0.1.1|ui-v0.1.2|native-v0.1.2|ui-v0.1.3|native-v0.1.3]" >&2; exit 2; fi
tmp="$1.rollback.$$"
trap 'rm -f "$tmp"' EXIT HUP INT TERM
case "${2:-blocker}" in
blocker)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
ui)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
native)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
ui-v0.1.1)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
native-v0.1.1)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
ui-v0.1.2)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
native-v0.1.2)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
ui-v0.1.3)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
native-v0.1.3)
base64 -d > "$tmp" <<'BASELINE_BYTES'

BASELINE_BYTES
;;
*) echo "Unknown rollback role" >&2; exit 2;;
esac
cat "$tmp" > "$1"
